'use strict';
const cloudConfig=window.GIORNO_CLOUD||{},cloudReady=!!(cloudConfig.url&&cloudConfig.publishableKey),cloud=cloudReady?supabase.createClient(cloudConfig.url,cloudConfig.publishableKey,{auth:{storageKey:'giorno-cloud-auth'}}):null;
let cloudUser=null,board=null,cloudBusy=false;
const cloudMessage=s=>$('cloudStatus').textContent=s;
function cloudRender(){$('cloudLogin').hidden=!!cloudUser||!cloudReady;$('cloudSetup').hidden=!!cloudUser||cloudReady;$('cloudGroupSetup').hidden=!cloudUser||!!board;$('cloudBoard').hidden=!board;$('cloudLogout').hidden=!cloudUser;
if(board){$('cloudHeading').textContent=board.title;$('cloudMembers').textContent='Con '+board.members.map(m=>m.name).join(', ');$('inviteMember').hidden=board.owner!==cloudUser.id;$('memberActions').innerHTML=board.members.filter(m=>m.id!==board.owner&&(board.owner===cloudUser.id||m.id===cloudUser.id)).map(m=>`<button class="quiet" data-remove-member="${m.id}">${m.id===cloudUser.id?'Lascia la famiglia':'Rimuovi '+esc(m.name)}</button>`).join('');}
if(window.renderDaily)window.renderDaily();}
function cloudRows(kind){if(!board)return '';return board.items.filter(x=>x.kind===kind).sort((a,b)=>Number(a.done)-Number(b.done)||a.title.localeCompare(b.title)).map(x=>`<article class="daily-row shared ${x.done?'finished':''}"><button class="tick" data-cloud-toggle="${x.id}" aria-label="${x.done?'Segna da fare':'Completa'}: ${esc(x.title)}" aria-pressed="${x.done}">${x.done?'\u2713':''}</button><div><strong>${esc(x.title)}</strong><p><span class="shared-tag">Condivisa</span>${esc(x.person||(kind==='shop'?'':'Da assegnare'))}</p></div>${kind==='family'?`<button class="quiet" data-cloud-claim="${x.id}">Me ne occupo</button>`:''}<button class="quiet" data-cloud-delete="${x.id}" aria-label="Elimina ${esc(x.title)}">Elimina</button></article>`).join('');}
function cloudAdd(kind,title,person){return cloudAction(async()=>{board=await cloudRPC('giorno_save_item',{p_id:crypto.randomUUID(),p_kind:kind,p_title:title,p_person:person||'',p_done:false,p_revision:0});});}

async function cloudRPC(name,args={}){const {data:result,error}=await cloud.rpc(name,args);if(error)throw error;return result;}
async function loadBoard(){if(!cloudUser||cloudBusy)return;try{board=await cloudRPC('giorno_board');cloudRender();cloudMessage('Aggiornato alle '+new Date().toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})+'.');}catch{cloudMessage('Sincronizzazione non disponibile. Le liste personali restano utilizzabili. Riprova quando sei online.');}}
async function cloudAction(fn){if(cloudBusy)return;cloudBusy=true;try{await fn();cloudRender();cloudMessage('Salvato online.');}catch(e){cloudMessage(String(e.message||'Operazione non riuscita. Riprova.').includes('CONFLICT')?'Un familiare ha appena modificato questa voce. La lista sarà aggiornata: controlla e riprova.':'Non è stato possibile salvare online. Controlla la connessione e riprova.');}finally{cloudBusy=false;}}
$('familyOnline').onclick=()=>{$('cloudDialog').showModal();cloudRender();loadBoard();};$('refreshCloud').onclick=loadBoard;
$('cloudLogin').onsubmit=async e=>{e.preventDefault();const email=$('cloudEmail').value.trim(),password=$('cloudPassword').value;cloudMessage('Accesso in corso…');const {error}=await cloud.auth.signInWithPassword({email,password});$('cloudPassword').value='';if(error)cloudMessage('Accesso non riuscito. Controlla email, password e conferma dell’email.');};
$('cloudSignup').onclick=async()=>{const email=$('cloudEmail').value.trim(),password=$('cloudPassword').value;if(!$('cloudEmail').checkValidity()||password.length<8){cloudMessage('Inserisci email e una password di almeno 8 caratteri.');return;}const {error}=await cloud.auth.signUp({email,password});$('cloudPassword').value='';cloudMessage(error?'Registrazione non riuscita. Riprova o usa Accedi.':'Controlla la tua email, conferma la registrazione e poi torna qui per accedere.');};
$('cloudLogout').onclick=async()=>{if(cloudBusy)return;try{if(window.stopPushOnLogout)await window.stopPushOnLogout();}catch{}const {error}=await cloud.auth.signOut();if(error){cloudMessage('Uscita non riuscita. Riprova quando sei online.');return;}board=null;cloudUser=null;cloudRender();cloudMessage('Hai effettuato l’uscita.');};
$('createFamily').onclick=()=>cloudAction(async()=>{board=await cloudRPC('giorno_create',{p_title:$('familyName').value.trim(),p_name:$('memberName').value.trim()});});
$('joinFamily').onclick=()=>cloudAction(async()=>{board=await cloudRPC('giorno_join',{p_token:$('inviteCode').value.trim(),p_name:$('memberName').value.trim()});$('inviteCode').value='';});
$('inviteMember').onclick=()=>cloudAction(async()=>{const token=await cloudRPC('giorno_invite');$('inviteOutput').hidden=false;$('inviteOutput').value=token;});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!board)return;const id=b.dataset.cloudToggle||b.dataset.cloudClaim||b.dataset.cloudDelete,x=board.items.find(x=>x.id===id);if(x){if(b.dataset.cloudDelete&&!confirm('Eliminare questa voce per tutti i familiari?'))return;cloudAction(async()=>{board=await cloudRPC(b.dataset.cloudDelete?'giorno_delete_item':'giorno_save_item',b.dataset.cloudDelete?{p_id:x.id,p_revision:x.revision}:{p_id:x.id,p_kind:x.kind,p_title:x.title,p_person:b.dataset.cloudClaim?(board.members.find(m=>m.id===cloudUser.id)?.name||'Io'):x.person,p_done:b.dataset.cloudToggle?!x.done:x.done,p_revision:x.revision});});}if(b.dataset.removeMember&&confirm('Confermi la rimozione dalla famiglia? L’accesso alle liste condivise verrà revocato.'))cloudAction(async()=>{board=await cloudRPC('giorno_remove_member',{p_user:b.dataset.removeMember});});});
if(cloud){cloud.auth.onAuthStateChange((_event,session)=>{cloudUser=session?.user||null;if(!cloudUser)board=null;cloudRender();if(cloudUser)setTimeout(()=>{loadBoard();if(window.queuePushSync)window.queuePushSync();},0);});setInterval(()=>{if(document.visibilityState==='visible'&&($('cloudDialog').open||area==='family'||area==='shop'))loadBoard();},10000);}
window.GiornoCloud={ready:cloudReady,rows:cloudRows,add:cloudAdd,count:kind=>board?board.items.filter(x=>x.kind===kind&&!x.done).length:0,joined:()=>!!board,signedIn:()=>!!cloudUser};
cloudRender();
